// The loader picks its part with a computed require() specifier, which
// scriptc does not compile natively: the package runs in a Node island.
import { createRequire } from "node:module";
const load = createRequire(import.meta.url);
const { Route } = ["./route.cjs"].map((p) => load(p))[0];
export function route(path, weight) {
  return new Route(path, weight);
}
export function heavier(a, b) {
  return Object.assign(b.weight > a.weight ? b : a, { rank: 1 });
}
